javascript-obfuscator.workedExample:
इनपुट:
function calculateTotal(price, taxRate) {
  const tax = price * taxRate;
  return price + tax;
}
const message = "Your total is: ";

तीनों रूपांतरण चालू होने पर आउटपुट बनता है:
function _0x0(price, taxRate) {
 const _0x1 = price * taxRate;
 return price + _0x1;
}
const _0x2 = "\x59\x6f\x75\x72\x20\x74\x6f\x74\x61\x6c\x20\x69\x73\x3a\x20";

calculateTotal बना _0x0, tax बना _0x1, message बना _0x2, कमेंट गायब, और "Your total is: " हेक्स एस्केप बन गया। कोड ठीक वही मान निकालता है।

